$lang['aff_theme_demo_home_heading'] = 'Earn more with our affiliate partner program';

$lang['aff_theme_demo_home_content'] = "Welcome partners. Promote our offers with your unique tracking links and see clicks, conversions, and commissions in real time from your dashboard.\n\nWe pay competitive commissions on qualified sales and leads. Request withdrawals when you reach the program threshold; most payouts are processed quickly during business days.\n\nYou get marketing assets, deep links where available, and reporting so you can optimize campaigns. Our support team can help with tracking, creatives, and compliance questions.\n\nJoin today, follow the program terms, and start earning from traffic you already reach.";

$lang['aff_theme_demo_about_content'] = "We built this platform so creators, publishers, and marketers can partner with brands they trust. Our affiliate program is designed for transparency: clear commission rules, reliable tracking, and fair attribution when customers convert through your links.\n\nWhether you run a blog, newsletter, comparison site, or paid traffic, you can use official creatives or request guidance on compliant promotion. We care about brand safety and partner reputation, so please read the policy tab for privacy, cookies, and acceptable use.\n\nIf you are new, start by generating your first tracking link after approval, test it in a staging click, then scale what works. We look forward to growing with you.";

$lang['aff_theme_demo_policy_heading'] = 'Privacy, data, and affiliate program notice (sample)';

$lang['aff_theme_demo_policy_html'] = '<h4>Introduction</h4><p>This sample page is for affiliate partners and visitors who use our marketing login area. Replace every section with text approved by your legal counsel before going live.</p><h4>Information we collect</h4><p>We may process account details you provide at registration (name, email, country), payment and tax information needed to pay commissions, technical data such as IP address and device type for security, and activity related to referral links (clicks, timestamps, and conversion events) to calculate rewards.</p><h4>Cookies and similar technologies</h4><p>We use cookies or local storage where needed for login sessions, preferences, fraud prevention, and analytics. Referral tracking may rely on cookies, link parameters, or server-side logs depending on your integration.</p><h4>How we use information</h4><p>Data is used to operate the platform, authenticate users, measure campaign performance, pay partners, meet legal obligations, and improve our services. We do not sell personal data as a product; any sharing is limited to processors, payment providers, or authorities when required.</p><h4>Retention and security</h4><p>We retain information as long as your account is active or as needed for tax, fraud, and dispute resolution. We apply reasonable technical and organizational safeguards; no method of transmission over the Internet is completely secure.</p><h4>Your choices</h4><p>You may update certain profile fields in your dashboard, opt out of non-essential communications where offered, or contact us to exercise rights available in your jurisdiction.</p><h4>Contact</h4><p>For privacy questions, contact your program administrator using the details published on the main site.</p>';

