$lang['payment_gateway_doc_info_p1'] = 'There are several payment methods available. Although sometimes you\'ll find yourself in a situation where you need something different, either there is no method available for your choice of payment gateway or you want different logic. In either case, you\'re left with the only option: To create a new payment method module.';

$lang['payment_gateway_doc_info_p2'] = 'We\'ll assume that our custom payment method name is "custom". There are at least three or four files and one folder you can create in order to set up everything. Let\'s check this in detail.';

$lang['payment_gateway_doc_info_p3'] = 'You need to create three files. Each file is required. The following is the folder structure.';

$lang['payment_gateway_doc_info_p4'] = 'You can create one additional folder and one file. Both folder and file are optional. The following is the folder structure.';

$lang['payment_gateway_doc_example'] = 'Example for custom.php';

$lang['payment_gateway_doc_sample_data'] = 'Get sample data';

$lang['payment_gateway_doc_folder_structure'] = 'Folder structure must be like this:';

$lang['payment_gateway_doc_controller_folder'] = 'Controller folder';

$lang['payment_gateway_doc_controller_info'] = 'This folder contains the custom.php file. This file contains all the logic of your payment gateway. Our payment gateway sends three types of requests to your controller. Every request has two parameters: $settingData and $gatewayData. You can get their sample data from';

$lang['payment_gateway_doc_controller_info_following_url'] = 'the following URL';

$lang['payment_gateway_doc_controller_info_sample_data_button'] = 'Get sample data button';

$lang['payment_gateway_doc_file_explanation'] = 'Explanation of file';

$lang['payment_gateway_doc_controller_explanation_1'] = 'must be file name';

$lang['payment_gateway_doc_controller_explanation_2'] = 'Name of payment gateway';

$lang['payment_gateway_doc_controller_explanation_3'] = 'Must be as it is. The api variable contains the CI object. You can use CI functionality';

$lang['payment_gateway_doc_controller_explanation_4'] = 'This function is required. We send this request to get your custom view file to show to the user.';

$lang['payment_gateway_doc_controller_explanation_5'] = 'This function is optional. This function prepares the request to send to your payment gateway.';

$lang['payment_gateway_doc_controller_explanation_6'] = 'This function is optional. This function accepts callbacks from your payment gateway. You can name the callback function whatever you want. If you want your custom function to be called by your payment gateway after payment completion, you must add your callback function name to $gatewayData["callback_url"] to send to your payment gateway in getPaymentGatewayView or setPaymentGatewayRequest.';

$lang['payment_gateway_doc_setting_folder'] = 'Setting folder';

$lang['payment_gateway_doc_setting_info'] = 'In this folder you can add your custom setting file. The setting file name must be the same as your payment method name. Also, the setting file must be located under the setting folder. Folder structure must be like this:';

$lang['payment_gateway_doc_setting_explanation'] = 'The setting file contains the $setting_data variable and this variable contains all saved settings of your payment gateway. Sometimes you need to ask for information from the admin, for example credentials of the payment gateway or something else. Also, you can manage the status of transactions in the project according to the result of the payment. $order_status lists are shown in the "Status ID And Title" section. You just need to create an input and our system will automatically create a setting page and save setting data.';

$lang['payment_gateway_doc_view_folder'] = 'View folder';

$lang['payment_gateway_doc_view_info'] = 'In this folder you can add your custom view file. The view file name must be the same as your payment method name. Also, the view file must be located under the view folder. Folder structure must be like this:';

$lang['payment_gateway_doc_view_explanation'] = 'The view file contains getPaymentGatewayView function parameters $settingData and $gatewayData. You can use them in the view file. In the view file you must send a request to $gatewayData["payment_confirmation"] like the above example. After getting a response from that request, you have two choices. In the first choice, you can directly redirect the user to the payment gateway page (e.g., using a form). In the second choice, you can send a request to $gatewayData["confirm_payment"], which means you call the setPaymentGatewayRequest method. Generally, the view file code structure depends on your payment gateway.';

$lang['payment_gateway_doc_library_folder'] = 'Library folder';

$lang['payment_gateway_doc_library_info'] = 'In this folder you can add your payment gateway source code if it exists. The library folder name must be the same as your payment method name. If you want to call it from the controller, you can do it with this line: require_once(APPPATH."payment_gateway/library/custom/.php"). Also, all payment method source code must be located under that folder. Folder structure must be like this:';

$lang['payment_gateway_doc_logo_folder'] = 'Logo folder';

$lang['payment_gateway_doc_logo_info'] = 'In this folder you can add your payment gateway logo if it exists. The logo name must be the same as your payment method name. Also, the logo must be located under the logo folder. Folder structure must be like this:';

$lang['payment_gateway_doc_payment_confirmation'] = 'Payment confirmation';

$lang['payment_gateway_doc_payment_confirmation_info'] = 'You must call this function after payment is completed. $gatewayData["id"] must not change. You must get $status_id from $settingData. If you want to send it directly, you can select the status from the "Status ID And Title" section. $transaction_id and $payment_status are optional.';

$lang['payment_gateway_doc_status_id_and_title'] = 'Status ID And Title';

$lang['payment_gateway_doc_zip_file'] = 'How to create zip file of payment method';

$lang['payment_gateway_doc_zip_info'] = 'Zip file name must be same with payment method name. Folder structure must be like this:';

