$lang['tour_marketing_welcome'] = 'Welcome to Marketing Tools! This is your campaign management center. Here you can create and manage all your affiliate marketing campaigns to drive traffic and conversions.';

$lang['tour_marketing_campaign_types'] = 'Choose your campaign type based on your marketing strategy:<br/>• <strong>Banner Ads</strong> - Visual advertisements for websites<br/>• <strong>Text Ads</strong> - Text-based promotional content<br/>• <strong>Link Ads</strong> - Direct promotional links<br/>• <strong>Video Ads</strong> - Video content for social media';

$lang['tour_marketing_create_button'] = 'Click the "Create New" button to start building your campaign. You\'ll be guided through setting up targeting, budget, and tracking options.';

$lang['tour_marketing_programs'] = 'Manage your affiliate programs here. Create different commission structures for different types of affiliates and track their performance.';

$lang['tour_marketing_categories'] = 'Organize your campaigns with categories. This helps you group similar campaigns together for better management and reporting.';

$lang['tour_marketing_dashboard'] = 'This dashboard shows your campaign performance metrics including clicks, conversions, and revenue. Monitor your ROI here.';

$lang['tour_marketing_analytics'] = 'Use the analytics section to track detailed performance data, identify top-performing campaigns, and optimize your marketing strategy.';

$lang['tour_store_welcome'] = 'Welcome to Store Management! This is your e-commerce control center where you can manage products, orders, and store settings to run your online business.';

$lang['tour_store_products'] = 'Manage your product catalog here. Add new products, set prices, manage inventory, and organize products by categories. You can also set up product variations and bulk upload products.';

$lang['tour_store_orders'] = 'View and manage all customer orders in real-time. Process payments, update order status, handle refunds, and track order fulfillment from this centralized location.';

$lang['tour_store_settings'] = 'Configure your store settings including commission rates for vendors, payment methods, shipping options, tax settings, and store policies.';

$lang['tour_store_categories'] = 'Organize your products with categories and subcategories. This helps customers find products easily and improves your store\'s navigation.';

$lang['tour_store_vendors'] = 'Manage your vendor network. Approve new vendors, set commission rates, track vendor performance, and handle vendor payments.';

$lang['tour_store_reports'] = 'Access detailed sales reports, revenue analytics, top-selling products, and vendor performance metrics to make data-driven business decisions.';

$lang['tour_membership_welcome'] = 'Welcome to Membership Management! Create and manage subscription-based access to your platform. Set up different membership tiers with varying benefits and pricing.';

$lang['tour_membership_plans'] = 'Create membership plans with different features:<br/>• <strong>Basic Plan</strong> - Essential features<br/>• <strong>Premium Plan</strong> - Advanced features<br/>• <strong>VIP Plan</strong> - Full access<br/>Set pricing, duration, and benefits for each plan.';

$lang['tour_membership_orders'] = 'View all membership orders and subscriptions. Monitor active members, track revenue, handle upgrades/downgrades, and manage subscription renewals.';

$lang['tour_membership_settings'] = 'Configure membership module settings including default plans, notification settings, expiration warnings, and membership features.';

$lang['tour_membership_members'] = 'Manage individual member accounts, view member activity, handle membership changes, and track member engagement and retention.';

$lang['tour_membership_analytics'] = 'Track membership metrics including sign-ups, cancellations, revenue per member, and membership growth trends to optimize your subscription business.';

$lang['tour_payment_welcome'] = 'Welcome to Payment Gateway Setup! Configure how your customers will pay for your services and products. Set up multiple payment methods for better conversion rates.';

$lang['tour_payment_gateways'] = 'Configure payment gateways like PayPal, Stripe, Razorpay, and others. Each gateway has different setup requirements and fee structures.';

$lang['tour_payment_settings'] = 'Set up payment preferences including currency, minimum amounts, processing fees, and automatic payment handling rules.';

$lang['tour_payment_security'] = 'Configure security settings for payments including fraud detection, SSL requirements, and PCI compliance settings.';

$lang['tour_wallet_welcome'] = 'Welcome to Wallet Management! Monitor and manage all financial transactions, user balances, and payment processing from this centralized location.';

$lang['tour_wallet_balance'] = 'View total wallet balance, pending transactions, and financial overview. Monitor cash flow and identify any discrepancies.';

$lang['tour_wallet_transactions'] = 'Track all wallet transactions including deposits, withdrawals, commissions, and refunds. Filter by date, amount, or transaction type.';

$lang['tour_store_welcome'] = 'Welcome to Store Management! This is your e-commerce control center where you can manage products, orders, inventory, and all store-related activities.';

$lang['tour_mlm_welcome'] = 'Welcome to MLM Settings! Configure your multi-level marketing structure, set commission rates, and manage affiliate levels for maximum network growth.';

$lang['tour_saas_welcome'] = 'Welcome to SaaS Platform Management! Configure vendor settings, manage deposits, and oversee your multi-tenant affiliate network platform.';

$lang['tour_award_welcome'] = 'Welcome to Award Level Management! Create achievement levels and reward tiers to motivate your affiliates and boost their performance.';

$lang['tour_wallet_settings'] = 'Configure wallet settings including minimum balances, transaction limits, and automatic processing rules.';

