$lang['min_health_score_promote_hint'] = '0 means any affiliate who can see this campaign may promote it. Higher values require a better Trust Score in the marketplace.';

$lang['min_award_level_promote'] = 'Minimum Award Level (optional)';

$lang['min_award_level_promote_none'] = 'Any level (health score only)';

$lang['min_award_level_promote_hint'] = 'Shown only when the Award Level module is enabled. Leave empty to ignore tier, or pick a minimum tier affiliates must have reached (by earnings ladder).';

$lang['min_award_level_hierarchy_tooltip'] = 'Note: Award level hierarchy is determined by the \'Minimum Earnings\' field. Ensure your levels are configured in ascending order.';

$lang['tour_store_dashboard_s1'] = 'This is your Store dashboard — a complete overview of your e-commerce performance. You can see total revenue, orders, products, and customers at a glance.';

$lang['tour_store_dashboard_s2'] = 'The KPI cards at the top show your key performance indicators: revenue, sales count, average order value, and customer count. Use them to spot trends quickly.';

$lang['tour_store_dashboard_s3'] = 'The hub cards give you fast access to every major store section — Products, Orders, Inventory, Categories, Coupons, Settings, Funnels, and more.';

$lang['tour_store_dashboard_s4'] = 'Use the Store sub-navigation bar at the top to jump between any store section without going back to the main menu.';

$lang['tour_store_products_s1'] = 'This is your Products list. Every product you sell through the store appears here with its price, stock, and status.';

$lang['tour_store_products_s2'] = 'Click "Add Product" to create a new product. You can set pricing, upload images, add variants, and configure inventory tracking from the product form.';

$lang['tour_store_products_s3'] = 'Use the Inventory tab inside this page to manage stock levels and variant combinations. Low-stock alerts help you reorder before running out.';

$lang['tour_store_orders_s1'] = 'The Orders page shows every purchase made through your store. Each row shows the customer, items, total, payment status, and fulfillment status.';

$lang['tour_store_orders_s2'] = 'Click on any order to open the detail view where you can update its status, add a tracking number, issue a refund, or send a notification to the customer.';

$lang['tour_store_orders_s3'] = 'Use the filters at the top to narrow orders by date range, status, or payment method. You can also export the filtered results to CSV.';

$lang['tour_membership_orders_s1'] = 'This is the Membership dashboard. It shows all active and past subscriptions across all your plans so you can track recurring revenue at a glance.';

$lang['tour_membership_orders_s2'] = 'Each row shows the member, the plan they subscribed to, the billing cycle, the next renewal date, and the current status (active, cancelled, expired).';

$lang['tour_membership_orders_s3'] = 'Use the navigation above to switch to Plans — where you create and manage subscription tiers — or to Settings to configure payment and billing behaviour.';

$lang['tour_membership_plans_s1'] = 'Plans are the subscription tiers your members can purchase. Each plan defines a price, billing interval (monthly/yearly), and the features or limits granted.';

$lang['tour_membership_plans_s2'] = 'Click "Create New Plan" to add a tier. Give it a clear name, set the price and interval, then define which features are included for subscribers of this plan.';

$lang['tour_membership_plans_s3'] = 'You can have multiple active plans simultaneously — for example a Basic, Pro, and Enterprise tier. Members can upgrade or downgrade between them.';

$lang['tour_membership_settings_s1'] = 'Membership Settings control the global behaviour of the subscription system: which payment gateway processes recurring charges, trial periods, and grace periods.';

$lang['tour_membership_settings_s2'] = 'Set your renewal reminder emails, failed payment retries, and cancellation policy here. These settings apply to all plans unless overridden at the plan level.';

$lang['tour_mlm_settings_s1'] = 'MLM Settings is where you define the rules of your multi-level marketing network: how many levels deep commissions travel and what percentage each level earns.';

$lang['tour_mlm_settings_s2'] = 'Set the commission rate per level carefully — the total of all levels combined should not exceed your product margin to keep the program profitable.';

$lang['tour_mlm_settings_s3'] = 'You can enable or disable the MLM module entirely here. Disabling it stops commission calculations but does not delete existing level data.';

$lang['tour_mlm_levels_s1'] = 'MLM Levels define the hierarchy in your affiliate network. Level 1 is the direct referrer, Level 2 is the referrer\'s referrer, and so on.';

$lang['tour_mlm_levels_s2'] = 'Each level can have its own commission rate. Click "Add Level" to extend the depth of your network. Most programs use 3-5 levels.';

$lang['tour_mlm_levels_s3'] = 'The "Jump Level" value sets a minimum sales threshold an affiliate must reach before commissions flow past them to the level above. Use this to reward active affiliates.';

$lang['tour_award_level_s1'] = 'Award Levels are achievement tiers that recognize top-performing affiliates. As affiliates earn more, they advance through levels and can unlock better commission rates or bonuses.';

$lang['tour_award_level_s2'] = 'Click "Create Award Level" to add a new tier. Set the minimum earnings required to reach it, a display name, and optionally a bonus reward granted on reaching it.';

$lang['tour_award_level_s3'] = 'Levels are ranked by their minimum earnings threshold. Make sure each level requires more than the previous one so progression is linear and motivating.';

$lang['tour_level_analysis_s1'] = 'The Level Analysis page gives you a breakdown of where your affiliates stand in the award level hierarchy and how close they are to advancing.';

$lang['tour_level_analysis_s2'] = 'The distribution chart shows how many affiliates are at each level. A healthy program has a pyramid shape — many at lower levels, fewer at the top.';

$lang['tour_level_analysis_s3'] = 'Use this data to spot affiliates close to levelling up and run targeted campaigns or incentives to push them over the threshold.';

$lang['tour_saas_settings_s1'] = 'SaaS Settings configure your multi-vendor platform. Here you set the admin fee percentage you take from each vendor sale, separately for Market Tools and Store.';

$lang['tour_saas_settings_s2'] = 'The Vendor Deposit tab lets you define how vendors top up their balance — which payment methods are accepted and minimum deposit amounts.';

$lang['tour_saas_settings_s3'] = 'The Vendor Permission tab controls what vendors can and cannot do on the platform — whether they can set their own commission rates, create coupons, and so on.';

$lang['tour_vendor_deposits_s1'] = 'This page lists all deposit transactions made by vendors. Each row shows the vendor, amount, payment method, transaction ID, and approval status.';

$lang['tour_vendor_deposits_s2'] = 'Click "Details" on any deposit to review proof of payment and manually approve or reject it. Approved deposits add to the vendor\'s available balance immediately.';

$lang['tour_vendor_deposits_s3'] = 'Use the filters to view deposits by vendor or date range. The total deposited amount is shown in the header as a quick reference.';

$lang['tour_campaigns_programs_s1'] = 'Programs define the commission structures available to your affiliates. Each program can have its own commission type — percentage, flat fee, or per-click — and its own rules.';

$lang['tour_campaigns_programs_s2'] = 'Click "Add New" to create a program. Choose the commission type, set the rate, and optionally restrict it to specific campaign categories or affiliate groups.';

$lang['tour_campaigns_programs_s3'] = 'Affiliates select a program when they join your network. Multiple programs let you offer different deals to different affiliate tiers or product categories.';

$lang['tour_campaigns_categories_s1'] = 'Campaign Categories let you organise your campaigns into logical groups — for example by product type, brand, or marketing channel.';

$lang['tour_campaigns_categories_s2'] = 'Affiliates can filter available campaigns by category, making it easier to find relevant offers. Click "Add Category" to create a new one and assign it to campaigns from the campaign form.';

$lang['tour_admin_user_s1'] = 'This page lists all administrator accounts on your platform. The Super Administrator has full access; all other admins are assigned a Role that limits their permissions.';

$lang['tour_admin_user_s2'] = 'Each admin can be assigned a predefined Role (e.g. Finance Admin, Support Admin) or given a Custom permission set unique to them. Roles make it easy to manage groups of admins consistently.';

$lang['tour_admin_user_s3'] = 'Click "Add New Admin" to create an account. You can set their password, assign a role, and specify their contact details. They will receive login credentials by email.';

$lang['tour_admin_roles_s1'] = 'Roles are reusable permission sets. Instead of configuring permissions for every admin individually, you create a Role once and assign it to multiple admins.';

$lang['tour_admin_roles_s2'] = 'Each Role is a collection of granular permissions — for example "can view orders", "can edit products", "can manage affiliates". Toggle them on or off to tailor access precisely.';

$lang['tour_admin_roles_s3'] = 'Click "Add New Role" to create a role from scratch, or use "Import Demo Roles" to load Finance, Support, and Marketing Admin presets as a starting point.';

$lang['tour_wallet_transactions_s1'] = 'The Wallet Transactions page shows every commission and payment entry across all affiliates. Each row shows the user, amount, type, and current payment status.';

$lang['tour_wallet_transactions_s2'] = 'Use the filters to search by user, date range, status, or commission type. You can also sort by amount to identify your highest earners quickly.';

$lang['tour_wallet_transactions_s3'] = 'Statuses include In Wallet (earned, not yet requested), Pending (withdrawal requested), Paid, and Rejected. You can bulk-update statuses using the checkboxes on the left.';

$lang['tour_wallet_requests_s1'] = 'Withdraw Requests lists all withdrawal requests submitted by affiliates. Each row shows the user, requested amount, preferred payment method, and current status.';

$lang['tour_wallet_requests_s2'] = 'Click on a request to open the detail view where you can approve or reject it, add a transaction ID as proof of payment, and leave a comment for the affiliate.';

$lang['tour_wallet_requests_s3'] = 'For batch processing, use the "Mass Payout Export" tab. It lets you export all pending requests in a format compatible with PayPal Mass Pay and similar services.';

$lang['tour_mass_payout_s1'] = 'Mass Payout lets you process many withdrawal requests at once. Export a CSV file in the format required by your payment processor, process the payments externally, then import the result file to mark them as paid.';

$lang['tour_mass_payout_s2'] = 'Click "Export" to download the pending requests. Process the payments in your payment processor (PayPal, bank, etc.), then click "Upload Return File" to import the confirmation file.';

$lang['tour_mass_payout_s3'] = 'Once the return file is uploaded, the system automatically updates each matching request to Paid and records the transaction ID. Affiliates are notified by email.';

$lang['tour_withdrawal_gateways_s1'] = 'Withdrawal Payment Gateways define which methods affiliates can use when requesting a payout — Bank Transfer, PayPal, Crypto, and so on.';

$lang['tour_withdrawal_gateways_s2'] = 'Click "Install Payment Gateway" to upload a custom gateway plugin in ZIP format, or download the Demo Gateway to see the expected file structure before building your own.';

$lang['tour_withdrawal_gateways_s3'] = 'Click the edit icon on any gateway to configure its settings — account details, minimum payout amount, and any instructions shown to affiliates during withdrawal.';

$lang['tour_wallet_settings_s1'] = 'Wallet Settings control how withdrawals work across your platform: manual approval vs. automatic, minimum withdrawal amounts, and wallet balance visibility to affiliates.';

$lang['tour_wallet_settings_s2'] = 'Set the minimum withdrawal threshold to reduce processing overhead — affiliates must accumulate at least this amount before they can request a payout.';

$lang['tour_wallet_settings_s3'] = 'Auto-withdrawal using a cron job sends payouts automatically when an affiliate\'s balance reaches the threshold, saving you from manually approving every request.';

